        return NULL;
    }

    // Buffer to store the output
    char *key = malloc(4096);  // Allocate a large enough buffer
    if (key == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pclose(fp);
        return NULL;
    }

