    else if (target_netloc.size() > domain.size() &&
             target_netloc.compare(target_netloc.size() - domain.size(), domain.size(), domain) == 0 &&
             target_netloc[target_netloc.size() - domain.size() - 1] == '.') {
        result = target;
    } else {
        result = "https://" + domain;
    }

    return result;
}

