    }

    // Create AES key (take first 16 bytes)
    std::vector<uint8_t> aes_key(key.begin(), key.begin() + AES_KEY_SIZE);

    // get a hard-coded IV
    std::vector<uint8_t> iv = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};

