*/
char* generate_receive_log(const char *msg) {
    // BEGIN SOLUTION
    // sanitize msg so that it does not contain newline or carriage return characters
    char sanitized_msg[MAX_MSG_LEN];
    for (int i = 0; i < strlen(msg); i++) {
        if (msg[i] == '\n' || msg[i] == '\r') {
