    if (log_entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Generate the log entry
    snprintf(log_entry, MAX_MSG_LEN + 40, "[%s] Received: %s", timestamp, sanitized_msg);

    return log_entry;
