    }

    // Write the content to the file
    file << content;
    if (file.fail()) {
        std::cerr << "Failed to write to file" << std::endl;
        umask(oldUmask); // Restore previous umask
        return;
    }

    // Close the file and restore the old umask
    file.close();
    umask(oldUmask);
    // END SOLUTION
}

